pub type Matrix<T> = Vec<Vec<T>>;

pub fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    assert!(a.len() > 0, "input array must be non-empty");
    assert!(shape.len() == 2, "shape must have length 2");

    let r = shape[0] as usize;
    let c = shape[1] as usize;

    assert!(r > 0 && c > 0, "shape entries must be positive");

    let n = a.len();
    assert!(
        n == r || n == c,
        "array length must equal R or C for broadcasting"
    );

    // Defensive: compute total size with checked math.
    let _total = r
        .checked_mul(c)
        .expect("R*C overflowed usize (unexpected for u8 inputs)");

    if n == r {
        // Treat `a` as a column vector: value depends on row index i, replicated across columns.
        let mut ret: Matrix<i8> = Vec::with_capacity(r);
        for i in 0..r {
            ret.push(vec![a[i]; c]);
        }
        ret
    } else {
        // Treat `a` as a row vector: value depends on column index j, replicated across rows.
        let mut ret: Matrix<i8> = Vec::with_capacity(r);
        for _ in 0..r {
            ret.push(a.clone());
        }
        ret
    }
}